using AgentPlatform.Application.Abstractions; using AgentPlatform.Domain.Llm; using Microsoft.EntityFrameworkCore;
namespace AgentPlatform.Infrastructure.Persistence;
public sealed class EfLlmConfigurationRepository(PlatformDbContext db) : ILlmConfigurationRepository { public async Task<IReadOnlyList<LlmConfiguration>> ListAsync(CancellationToken ct) => await db.LlmConfigurations.AsNoTracking().OrderBy(x => x.Name).ToArrayAsync(ct); public Task<LlmConfiguration?> FindAsync(Guid id, CancellationToken ct) => db.LlmConfigurations.SingleOrDefaultAsync(x => x.Id == id, ct); public Task AddAsync(LlmConfiguration item, CancellationToken ct) => db.LlmConfigurations.AddAsync(item, ct).AsTask(); public void Remove(LlmConfiguration item) => db.LlmConfigurations.Remove(item); public Task SaveChangesAsync(CancellationToken ct) => db.SaveChangesAsync(ct); }
